fn main() -> eframe::Result<()> {
    if let Some((url, output_dir)) = page_loader_worker_invocation() {
        if let Err(error) = run_page_loader_worker(&url, &output_dir) {
            eprintln!("page loader worker failed: {error}");
            std::process::exit(1);
        }
        std::process::exit(0);
    }

    let config = AppConfig::from_args();
    let options = NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_inner_size([1040.0, 720.0])
            .with_title(APP_TITLE),
        ..Default::default()
    };

    eframe::run_native(
        APP_TITLE,
        options,
        Box::new(move |cc| Ok(Box::new(AlmostThereApp::new(cc, config)))),
    )
}

#[derive(Clone, Debug, Default)]
struct AppConfig {
    record_events: bool,
    debug_socket: bool,
    event_trace: bool,
    debug_links: bool,
    debug_image_loading: bool,
    page_loader_timeout_enabled: bool,
    initial_url: Option<String>,
    trace_items: Vec<String>,
}

impl AppConfig {
    fn from_args() -> Self {
        let args: Vec<String> = std::env::args().skip(1).collect();
        Self::from_arg_values(args)
    }

    fn from_arg_values(args: Vec<String>) -> Self {
        let mut record_events = false;
        let mut debug_socket = false;
        let mut event_trace = false;
        let mut debug_links = false;
        let mut debug_image_loading = false;
        let mut page_loader_timeout_override = None;
        let mut initial_url = None;
        let mut trace_items = Vec::new();
        let mut index = 0usize;
        while index < args.len() {
            let arg = &args[index];
            if arg == "--record-events" {
                record_events = true;
            } else if arg == "--debug-socket" {
                debug_socket = true;
            } else if arg == "--event-trace" {
                event_trace = true;
            } else if arg == "--debug-links" {
                debug_links = true;
            } else if arg == "--debug-image-loading" {
                debug_image_loading = true;
            } else if arg == "--page-loader-timeout" || arg == "--debug-page-loader-timeout" {
                page_loader_timeout_override = Some(true);
            } else if arg == "--no-page-loader-timeout" {
                page_loader_timeout_override = Some(false);
            } else if arg == "--trace-item" || arg == "--track-item" {
                if let Some(value) = args.get(index + 1) {
                    trace_items.push(value.to_owned());
                    index += 1;
                }
            } else if let Some(value) = arg.strip_prefix("--trace-item=") {
                trace_items.push(value.to_owned());
            } else if let Some(value) = arg.strip_prefix("--track-item=") {
                trace_items.push(value.to_owned());
            } else if !arg.starts_with('-') && initial_url.is_none() {
                initial_url = Some(arg.to_owned());
            }
            index += 1;
        }

        if event_trace && trace_items.is_empty() {
            trace_items = DEFAULT_EVENT_TRACE_ITEMS
                .iter()
                .map(|item| (*item).to_owned())
                .collect();
        }

        Self {
            record_events,
            debug_socket,
            event_trace,
            debug_links,
            debug_image_loading,
            page_loader_timeout_enabled: page_loader_timeout_override.unwrap_or(false),
            initial_url,
            trace_items,
        }
    }
}

const PAGE_LOADER_WORKER_FLAG: &str = "--page-loader-worker";
const PAGE_LOADER_WORKER_TIMEOUT_SECS: u64 = 120;
const PAGE_LOADER_WORKER_POLL_MS: u64 = 50;

fn page_loader_worker_invocation() -> Option<(String, PathBuf)> {
    let mut args = std::env::args().skip(1);
    let flag = args.next()?;
    if flag != PAGE_LOADER_WORKER_FLAG {
        return None;
    }
    let url = args.next()?;
    let output_dir = args.next().map(PathBuf::from)?;
    Some((url, output_dir))
}

fn run_page_loader_worker(url: &str, output_dir: &Path) -> io::Result<()> {
    fs::create_dir_all(output_dir)?;
    let _ = WORKER_TRACE_PATH.set(output_dir.join("worker_trace.jsonl"));
    let output_dir_text = output_dir.display().to_string();
    emit_global_telemetry(
        "navigation.worker.output_dir.ready",
        &[("url", url), ("output_dir", &output_dir_text)],
    );
    emit_global_telemetry("navigation.fetch.started", &[("url", url)]);
    let source = load_url_source(url)?;
    let final_url = source.source.clone();
    emit_global_telemetry(
        "navigation.fetch.completed",
        &[
            ("url", url),
            ("final_url", &final_url),
            ("html_bytes", &source.html.len().to_string()),
            (
                "body_bytes",
                &source
                    .image
                    .as_ref()
                    .map(|image| image.bytes.len())
                    .unwrap_or_else(|| source.html.len())
                    .to_string(),
            ),
            (
                "content_kind",
                if source.image.is_some() {
                    "image"
                } else {
                    "html"
                },
            ),
        ],
    );
    emit_global_telemetry(
        "navigation.artifacts.prepare.started",
        &[("url", url), ("final_url", &final_url)],
    );
    let prepared = prepare_navigation_artifacts(source)?;
    emit_global_telemetry(
        "navigation.artifacts.prepare.completed",
        &[("url", url), ("final_url", &prepared.source)],
    );
    emit_global_telemetry(
        "navigation.artifacts.write.started",
        &[("url", url), ("final_url", &prepared.source)],
    );
    write_worker_prepared_navigation(output_dir, &prepared)?;
    emit_global_telemetry(
        "navigation.artifacts.write.completed",
        &[("url", url), ("final_url", &prepared.source)],
    );
    Ok(())
}

