    #[test]
    fn selected_text_copies_soft_wrapped_paragraph_lines_as_spaces() {
        let html = r#"
            <html>
              <head>
                <style>
                  p { width: 140px; font-size: 16px; }
                </style>
              </head>
              <body>
                <p>Alpha beta gamma delta epsilon zeta eta theta.</p>
              </body>
            </html>
        "#;
        let document = parse_html_document(html, "https://example.test/soft-wrap-copy");
        let rich_lines = document
            .canvas_graph
            .objects
            .iter()
            .enumerate()
            .filter_map(|(index, object)| match object {
                CanvasObject::RichTextLine(line) => Some((index, line)),
                _ => None,
            })
            .collect::<Vec<_>>();

        assert!(
            rich_lines.len() >= 2,
            "expected paragraph to wrap into rich lines: {rich_lines:?}"
        );
        assert_eq!(
            rich_lines[0].1.selection_break_before,
            rich_canvas::CanvasSelectionBreak::Hard
        );
        assert_eq!(
            rich_lines[1].1.selection_break_before,
            rich_canvas::CanvasSelectionBreak::Soft
        );

        let last_text = rich_lines
            .last()
            .expect("expected last rich line")
            .1
            .spans
            .iter()
            .map(|span| span.text.as_str())
            .collect::<String>();
        let selection = rich_canvas::CanvasTextSelection {
            anchor: Some(rich_canvas::CanvasTextCaret {
                object_index: rich_lines[0].0,
                char_index: 0,
            }),
            focus: Some(rich_canvas::CanvasTextCaret {
                object_index: rich_lines.last().expect("last rich line").0,
                char_index: last_text.chars().count(),
            }),
            dragging: false,
            drag_exceeded_click: false,
        };

        assert_eq!(
            rich_canvas::canvas_graph_selected_text(&document.canvas_graph, &selection).as_deref(),
            Some("Alpha beta gamma delta epsilon zeta eta theta.")
        );
    }

    #[test]
    fn linked_inline_fragments_advance_and_rect_use_measured_text_width() {
        let style = ResolvedBoxStyle {
            font_size: 10.0,
            visibility_visible: true,
            opacity: 1.0,
            ..ResolvedBoxStyle::default()
        };
        let runs = vec![CanvasInlineRun {
            text: "Link".to_owned(),
            replaced: None,
            style: style.clone(),
            href: Some("#link".to_owned()),
            element_id: None,
            preserve_whitespace: false,
        }];

        let lines = build_canvas_line_boxes(runs, None, 200.0);
        assert_eq!(lines.len(), 1);
        let fragment = &lines[0].fragments[0];
        let raw_size = measure_canvas_text_run(None, "Link", &style);

        assert_eq!(fragment.text_inset_x, 0.0);
        assert_eq!(fragment.trailing_bearing_x, 0.0);
        assert!(
            (fragment.advance_x - raw_size.x).abs() < 0.5,
            "linked inline flow should advance by measured glyph width, not link side bearing"
        );
        assert!(
            (lines[0].width - raw_size.x).abs() < 0.5,
            "line width should follow measured text flow"
        );
        assert!(
            (fragment.size.x - raw_size.x).abs() < 0.5,
            "linked inline fragment rect should match measured text width"
        );
    }

