    #[test]
    fn preformatted_colored_inline_code_preserves_tag_boundary_spaces() {
        let document = parse_html_document(
            r##"
            <pre><code><span style="color:#aa6600">#include</span> <span style="color:#336699">&lt;stdio.h&gt;</span>
<span style="color:#aa0066">int</span> <span style="color:#0033aa">main</span>(void) { return 0; }</code></pre>
            "##,
            "about:test",
        );

        let include_line = document
            .canvas_graph
            .objects
            .iter()
            .find_map(|object| match object {
                CanvasObject::RichTextLine(line)
                    if line.spans.iter().any(|span| span.text == "#include") =>
                {
                    Some(line)
                }
                _ => None,
            })
            .expect("line with #include");
        let include_span = include_line
            .spans
            .iter()
            .find(|span| span.text == "#include")
            .expect("#include");
        let header_span = include_line
            .spans
            .iter()
            .find(|span| span.text == "<stdio.h>")
            .expect("<stdio.h>");
        let include_space = document
            .canvas_graph
            .objects
            .iter()
            .find_map(|object| match object {
                CanvasObject::RichTextLine(line)
                    if line.spans.iter().any(|span| span.text == "#include") =>
                {
                    line.spans.iter().find(|span| span.text == " ")
                }
                _ => None,
            })
            .expect("space after colored #include");
        let int_line = document
            .canvas_graph
            .objects
            .iter()
            .find_map(|object| match object {
                CanvasObject::RichTextLine(line)
                    if line.spans.iter().any(|span| span.text == "int") =>
                {
                    Some(line)
                }
                _ => None,
            })
            .expect("line with int");
        let int_keyword = int_line
            .spans
            .iter()
            .find(|span| span.text == "int")
            .expect("int");
        let main = int_line
            .spans
            .iter()
            .find(|span| span.text == "main")
            .expect("main");

        assert_eq!(
            include_span.color,
            egui::Color32::from_rgb(0xaa, 0x66, 0x00)
        );
        assert_eq!(header_span.color, egui::Color32::from_rgb(0x33, 0x66, 0x99));
        assert_eq!(int_keyword.color, egui::Color32::from_rgb(0xaa, 0x00, 0x66));
        assert_eq!(main.color, egui::Color32::from_rgb(0x00, 0x33, 0xaa));
        assert_eq!(include_space.text, " ");
        assert!(
            int_line.rect.top() > include_line.rect.top(),
            "preformatted newline should move colored code to the next line"
        );
        assert!(int_line.spans.iter().any(|span| span.text == " "));
    }

    #[test]
    fn canvas_graph_table_colspan_expands_cell_width() {
        let document = parse_html_document(
            r##"
            <html>
              <body style="padding: 0;">
                <table>
                  <tr><th colspan="2">Wide</th><th>Right</th></tr>
                  <tr><td>Left</td><td>Middle</td><td>Tail</td></tr>
                </table>
              </body>
            </html>
            "##,
            "https://example.test/",
        );

        let wide = find_canvas_cell_rect(&document.canvas_graph, "Wide").expect("wide cell");
        let right = find_canvas_cell_rect(&document.canvas_graph, "Right").expect("right cell");
        let left = find_canvas_cell_rect(&document.canvas_graph, "Left").expect("left cell");
        let middle = find_canvas_cell_rect(&document.canvas_graph, "Middle").expect("middle cell");

        assert!(
            wide.rect.width() > right.rect.width() * 1.8,
            "expected colspan cell {:?} to be about two slots wide vs {:?}",
            wide.rect,
            right.rect
        );
        assert_eq!(wide.rect.left(), left.rect.left());
        assert!(middle.rect.left() > left.rect.left());
        assert!(right.rect.left() > middle.rect.left());
    }

    #[test]
    fn canvas_graph_table_rowspan_reserves_following_row_slot() {
        let document = parse_html_document(
            r##"
            <html>
              <body style="padding: 0;">
                <table>
                  <tr><td rowspan="2">Tall</td><td>Top</td></tr>
                  <tr><td>Bottom</td></tr>
                </table>
              </body>
            </html>
            "##,
            "https://example.test/",
        );

        let tall = find_canvas_cell_rect(&document.canvas_graph, "Tall").expect("tall cell");
        let top = find_canvas_cell_rect(&document.canvas_graph, "Top").expect("top cell");
        let bottom = find_canvas_cell_rect(&document.canvas_graph, "Bottom").expect("bottom cell");

        assert!(
            tall.rect.height() > top.rect.height() * 1.8,
            "expected rowspan cell {:?} to span two row heights vs {:?}",
            tall.rect,
            top.rect
        );
        assert_eq!(top.rect.left(), bottom.rect.left());
        assert!(top.rect.left() >= tall.rect.right());
        assert!(bottom.rect.top() > top.rect.top());
    }

    #[test]
    fn css_display_table_roles_generate_table_cells() {
        let document = parse_html_document(
            r##"
            <html>
              <head>
                <style>
                  .forecast { display: table; width: 600px; }
                  .row { display: table-row; }
                  .cell { display: table-cell; padding: 4px; }
                  .time { width: 15%; }
                  .description { width: 55%; }
                  .temp { width: 30%; }
                </style>
              </head>
              <body style="padding: 0;">
                <div class="forecast">
                  <div class="row">
                    <div class="cell time">15:00</div>
                    <div class="cell description">Sereno con foschia</div>
                    <div class="cell temp">25 C</div>
                  </div>
                </div>
              </body>
            </html>
            "##,
            "https://example.test/",
        );

        let time = find_canvas_cell_rect(&document.canvas_graph, "15:00").expect("time cell");
        let description = find_canvas_cell_rect(&document.canvas_graph, "Sereno con foschia")
            .expect("description cell");
        let temp = find_canvas_cell_rect(&document.canvas_graph, "25 C").expect("temp cell");

        assert!(description.rect.left() > time.rect.left());
        assert!(temp.rect.left() > description.rect.left());
        assert!(
            description.rect.width() > time.rect.width(),
            "CSS table roles should preserve declared table-cell sizing: {:?} vs {:?}",
            description.rect,
            time.rect
        );
    }

