    #[test]
    fn color_layout_ecosia_logical_centering_fixtures_match_reference_geometry() {
        let fixture_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../color_layout_test");
        let cases = [
            (
                "104_ecosia_logical_margin_centering.html",
                egui::Color32::from_rgb(77, 171, 247),
                egui::Rect::from_min_max(egui::pos2(160.0, 24.0), egui::pos2(1120.0, 120.0)),
            ),
            (
                "105_ecosia_inline_size_centering.html",
                egui::Color32::from_rgb(77, 171, 247),
                egui::Rect::from_min_max(egui::pos2(160.0, 24.0), egui::pos2(1120.0, 112.0)),
            ),
            (
                "106_ecosia_app_container_logical_vars.html",
                egui::Color32::from_rgb(77, 171, 247),
                egui::Rect::from_min_max(egui::pos2(160.0, 24.0), egui::pos2(1120.0, 114.0)),
            ),
            (
                "107_ecosia_result_grid_logical_gutters.html",
                egui::Color32::from_rgb(77, 171, 247),
                egui::Rect::from_min_max(egui::pos2(206.0, 24.0), egui::pos2(1170.0, 88.0)),
            ),
            (
                "108_ecosia_logical_padding_search_header.html",
                egui::Color32::from_rgb(77, 171, 247),
                egui::Rect::from_min_max(egui::pos2(160.0, 16.0), egui::pos2(280.0, 80.0)),
            ),
        ];

        for (fixture_name, fill, expected) in cases {
            let fixture = fixture_dir.join(fixture_name);
            let html = fs::read_to_string(&fixture)
                .unwrap_or_else(|error| panic!("failed to read {}: {error}", fixture.display()));
            let document = parse_html_document(&html, &path_to_file_url(&fixture));
            let rect = find_canvas_rect_by_fill(&document.canvas_graph, fill)
                .unwrap_or_else(|| panic!("missing target rect in {fixture_name}"));

            assert!(
                (rect.rect.left() - expected.left()).abs() <= 1.5,
                "{fixture_name} left mismatch: got {:?}, expected {:?}",
                rect.rect,
                expected
            );
            assert!(
                (rect.rect.top() - expected.top()).abs() <= 1.5,
                "{fixture_name} top mismatch: got {:?}, expected {:?}",
                rect.rect,
                expected
            );
            assert!(
                (rect.rect.width() - expected.width()).abs() <= 2.5,
                "{fixture_name} width mismatch: got {:?}, expected {:?}",
                rect.rect,
                expected
            );
        }
    }

    #[test]
    #[ignore = "requires Chrome/Chromium; run with CHROME_BIN=/path/to/chrome cargo test -p almostthere_browser color_layout_fixtures_generate_static_pngs -- --ignored --nocapture"]
    fn color_layout_fixtures_generate_static_pngs() {
        let chrome = find_chrome_binary().expect(
            "set CHROME_BIN or install chromium/google-chrome to render color layout references",
        );
        let almost_renderer = ColorLayoutAlmostRenderer::from_env();
        let fixture_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../color_layout_test");
        let mut fixtures = fs::read_dir(&fixture_dir)
            .unwrap_or_else(|error| {
                panic!(
                    "failed to read color layout fixture dir {}: {error}",
                    fixture_dir.display()
                )
            })
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .filter(|path| {
                path.extension().and_then(|ext| ext.to_str()) == Some("html")
                    && path
                        .file_name()
                        .and_then(|name| name.to_str())
                        .is_some_and(|name| name.as_bytes().first().is_some_and(u8::is_ascii_digit))
            })
            .collect::<Vec<_>>();
        fixtures.sort();
        assert!(
            fixtures.len() >= 50,
            "expected at least the original 50 numbered color layout fixtures"
        );

        let report_dir =
            Path::new(env!("CARGO_MANIFEST_DIR")).join("../target/color_layout_reference");
        fs::create_dir_all(&report_dir).expect("failed to create color layout report dir");

        let mut index_rows = Vec::new();
        for fixture in fixtures {
            let name = fixture
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("<unknown>")
                .to_owned();
            let html = fs::read_to_string(&fixture)
                .unwrap_or_else(|error| panic!("failed to read {}: {error}", fixture.display()));
            let stem = fixture
                .file_stem()
                .and_then(|stem| stem.to_str())
                .unwrap_or("fixture");
            let chrome_png = report_dir.join(format!("{stem}.chrome.png"));
            let almost_png = report_dir.join(format!("{stem}.almostthere.png"));
            let paired_png = report_dir.join("paired").join(format!("{stem}.paired.png"));

            render_chrome_color_layout_png(&chrome, &fixture, &chrome_png);
            render_almostthere_color_layout_png(&html, &fixture, &almost_png, almost_renderer);
            write_color_layout_paired_png(&almost_png, &chrome_png, &paired_png);

            index_rows.push(format!(
                r#"<section class="pair"><h2>{}</h2><div><figure class="wide"><figcaption>Paired: This browser | Reference</figcaption><img src="{}"></figure><figure><figcaption>This browser</figcaption><img src="{}"></figure><figure><figcaption>Reference</figcaption><img src="{}"></figure></div></section>"#,
                html_escape(&name),
                html_escape(
                    paired_png
                        .strip_prefix(&report_dir)
                        .ok()
                        .and_then(|path| path.to_str())
                        .unwrap_or("")
                ),
                html_escape(almost_png.file_name().and_then(|name| name.to_str()).unwrap_or("")),
                html_escape(chrome_png.file_name().and_then(|name| name.to_str()).unwrap_or(""))
            ));
        }

        let index_path = report_dir.join("index.html");
        fs::write(&index_path, color_layout_reference_index(&index_rows))
            .expect("failed to write color layout reference index");
        eprintln!("color layout PNG review index: {}", index_path.display());
    }

    fn find_chrome_binary() -> Option<PathBuf> {
        if let Ok(path) = std::env::var("CHROME_BIN") {
            let path = PathBuf::from(path);
            if chrome_binary_works(&path) {
                return Some(path);
            }
        }

        [
            "chromium",
            "chromium-browser",
            "google-chrome",
            "google-chrome-stable",
            "chrome",
        ]
        .into_iter()
        .map(PathBuf::from)
        .find(|candidate| chrome_binary_works(candidate))
    }

    fn chrome_binary_works(path: &Path) -> bool {
        std::process::Command::new(path)
            .arg("--version")
            .output()
            .is_ok_and(|output| output.status.success())
    }

    fn render_chrome_color_layout_png(chrome: &Path, fixture: &Path, output_path: &Path) {
        let output = std::process::Command::new(chrome)
            .arg("--headless=new")
            .arg("--disable-gpu")
            .arg("--no-sandbox")
            .arg("--disable-dev-shm-usage")
            .arg("--allow-file-access-from-files")
            .arg("--window-size=1280,1800")
            .arg(format!("--screenshot={}", output_path.display()))
            .arg(path_to_file_url(fixture))
            .output()
            .unwrap_or_else(|error| panic!("failed to run Chrome {}: {error}", chrome.display()));

        assert!(
            output.status.success(),
            "Chrome failed for {}:\n{}",
            fixture.display(),
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum ColorLayoutAlmostRenderer {
        Browser,
        Synthetic,
    }

    impl ColorLayoutAlmostRenderer {
        fn from_env() -> Self {
            match std::env::var("COLOR_LAYOUT_RENDERER")
                .unwrap_or_else(|_| "synthetic".to_owned())
                .to_ascii_lowercase()
                .as_str()
            {
                "synthetic" | "debug" | "fast" => Self::Synthetic,
                "browser" | "actual" | "window" => Self::Browser,
                other => panic!(
                    "unsupported COLOR_LAYOUT_RENDERER={other:?}; use 'browser' or 'synthetic'"
                ),
            }
        }
    }

    fn render_almostthere_color_layout_png(
        html: &str,
        fixture: &Path,
        output_path: &Path,
        renderer: ColorLayoutAlmostRenderer,
    ) {
        let source = path_to_file_url(fixture);
        let document = parse_html_document(html, &source);
        match renderer {
            ColorLayoutAlmostRenderer::Browser => {
                capture_color_layout_browser_window(document, output_path).unwrap_or_else(
                    |error| panic!("failed to capture {}: {error}", fixture.display()),
                );
            }
            ColorLayoutAlmostRenderer::Synthetic => {
                let image = rasterize_canvas_graph_debug_frame(&document.canvas_graph);
                image.save(output_path).unwrap_or_else(|error| {
                    panic!("failed to write {}: {error}", output_path.display())
                });
            }
        }
    }

    #[derive(Default)]
    struct ColorLayoutCaptureResult {
        path: Option<PathBuf>,
        error: Option<String>,
    }

    struct ColorLayoutCaptureApp {
        canvas: BrowserCanvas,
        document: BrowserDocument,
        output_path: PathBuf,
        result: Arc<Mutex<ColorLayoutCaptureResult>>,
        requested: bool,
        captured: bool,
    }

    impl App for ColorLayoutCaptureApp {
        fn update(&mut self, ctx: &egui::Context, _frame: &mut Frame) {
            ctx.set_visuals(egui::Visuals::light());
            self.handle_screenshot_events(ctx);
            if self.captured {
                ctx.send_viewport_cmd(egui::ViewportCommand::Close);
                return;
            }

            egui::CentralPanel::default()
                .frame(
                    egui::Frame::new()
                        .fill(self.document.style.page_background)
                        .inner_margin(egui::Margin::ZERO)
                        .outer_margin(egui::Margin::ZERO),
                )
                .show(ctx, |ui| {
                    let _ = self.canvas.ui(ui, &mut self.document);
                });

            if !self.requested {
                ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::UserData::new(
                    "color_layout_capture",
                )));
                self.requested = true;
            }
            ctx.request_repaint();
        }
    }

    impl ColorLayoutCaptureApp {
        fn handle_screenshot_events(&mut self, ctx: &egui::Context) {
            let events = ctx.input(|input| input.events.clone());
            for event in events {
                let egui::Event::Screenshot { image, .. } = event else {
                    continue;
                };

                if let Err(error) = color_image_to_rgba(&image).save(&self.output_path) {
                    if let Ok(mut result) = self.result.lock() {
                        result.error = Some(error.to_string());
                    }
                } else if let Ok(mut result) = self.result.lock() {
                    result.path = Some(self.output_path.clone());
                }
                self.captured = true;
                ctx.send_viewport_cmd(egui::ViewportCommand::Close);
            }
        }
    }

    fn capture_color_layout_browser_window(
        document: BrowserDocument,
        output_path: &Path,
    ) -> io::Result<()> {
        capture_color_layout_browser_window_with_size(
            document,
            egui::vec2(1280.0, 1800.0),
            output_path,
        )
    }

    fn capture_color_layout_browser_window_with_size(
        document: BrowserDocument,
        window_size: egui::Vec2,
        output_path: &Path,
    ) -> io::Result<()> {
        capture_color_layout_browser_window_with_size_and_scroll(
            document,
            window_size,
            egui::Vec2::ZERO,
            output_path,
        )
    }

    fn capture_color_layout_browser_window_with_size_and_scroll(
        document: BrowserDocument,
        window_size: egui::Vec2,
        scroll_offset: egui::Vec2,
        output_path: &Path,
    ) -> io::Result<()> {
        let result = Arc::new(Mutex::new(ColorLayoutCaptureResult::default()));
        let app_result = Arc::clone(&result);
        let output_path = output_path.to_path_buf();
        let options = NativeOptions {
            viewport: egui::ViewportBuilder::default()
                .with_inner_size(window_size)
                .with_resizable(false)
                .with_decorations(false)
                .with_title("AlmostThere Color Layout Capture"),
            event_loop_builder: Some(Box::new(|builder| {
                #[cfg(target_os = "linux")]
                {
                    winit::platform::x11::EventLoopBuilderExtX11::with_any_thread(builder, true);
                    winit::platform::wayland::EventLoopBuilderExtWayland::with_any_thread(
                        builder, true,
                    );
                }
            })),
            vsync: false,
            ..Default::default()
        };

        eframe::run_native(
            "AlmostThere Color Layout Capture",
            options,
            Box::new(move |cc| {
                configure_browser_fonts(&cc.egui_ctx);
                Ok(Box::new(ColorLayoutCaptureApp {
                    canvas: BrowserCanvas {
                        zoom: 1.0,
                        scroll_offset,
                        last_viewport_rect: None,
                        hovered_link_href: None,
                        hovered_link_element_id: None,
                        text_selection: Default::default(),
                    },
                    document,
                    output_path,
                    result: app_result,
                    requested: false,
                    captured: false,
                }))
            }),
        )
        .map_err(|error| io::Error::other(error.to_string()))?;

        let result = Arc::try_unwrap(result)
            .map_err(|_| io::Error::other("capture result still has owners"))?
            .into_inner()
            .map_err(|_| io::Error::other("capture result lock was poisoned"))?;

        if let Some(error) = result.error {
            return Err(io::Error::other(error));
        }
        if result.path.is_none() {
            return Err(io::Error::other("window screenshot was not captured"));
        }
        Ok(())
    }

    fn capture_color_layout_browser_full_page(
        document: &BrowserDocument,
        output_path: &Path,
    ) -> io::Result<()> {
        let tile_size = egui::vec2(1280.0, 1400.0);
        let content_height = document.canvas_graph.viewport.y.ceil().max(tile_size.y) as u32;
        let width = tile_size.x.ceil() as u32;
        let tile_height = tile_size.y.ceil() as u32;
        let tile_dir = output_path
            .parent()
            .unwrap_or_else(|| Path::new("."))
            .join("ilmeteo_palermo_actual_browser_tiles");
        fs::create_dir_all(&tile_dir)?;

        let mut stitched = image::RgbaImage::new(width, content_height);
        let mut y = 0u32;
        let mut tile_index = 0usize;
        while y < content_height {
            let tile_path = tile_dir.join(format!("tile_{tile_index:03}.png"));
            capture_color_layout_browser_window_with_size_and_scroll(
                document.clone(),
                tile_size,
                egui::vec2(0.0, y as f32),
                &tile_path,
            )?;
            let tile = image::open(&tile_path)
                .map_err(io::Error::other)?
                .to_rgba8();
            let copy_width = width.min(tile.width());
            let remaining_height = content_height - y;
            let copy_height = remaining_height.min(tile_height).min(tile.height());
            for row in 0..copy_height {
                for col in 0..copy_width {
                    stitched.put_pixel(col, y + row, *tile.get_pixel(col, row));
                }
            }
            y += copy_height.max(1);
            tile_index += 1;
        }

        stitched.save(output_path).map_err(io::Error::other)
    }

    fn color_image_to_rgba(image: &egui::ColorImage) -> image::RgbaImage {
        let mut rgba = image::RgbaImage::new(image.size[0] as u32, image.size[1] as u32);
        for (index, color) in image.pixels.iter().enumerate() {
            let x = (index % image.size[0]) as u32;
            let y = (index / image.size[0]) as u32;
            rgba.put_pixel(
                x,
                y,
                image::Rgba([color.r(), color.g(), color.b(), color.a()]),
            );
        }
        rgba
    }

    fn write_color_layout_paired_png(almost_png: &Path, chrome_png: &Path, output_path: &Path) {
        let this_browser = image::open(almost_png)
            .unwrap_or_else(|error| panic!("failed to read {}: {error}", almost_png.display()))
            .to_rgba8();
        let reference = image::open(chrome_png)
            .unwrap_or_else(|error| panic!("failed to read {}: {error}", chrome_png.display()))
            .to_rgba8();
        let panel_width = this_browser.width().max(reference.width());
        let panel_content_height = this_browser.height().max(reference.height());
        let margin = 28;
        let header_height = 58;
        let divider_width = 18;
        let canvas_width = margin * 2 + panel_width * 2 + divider_width;
        let canvas_height = margin * 2 + header_height + panel_content_height;
        let mut canvas = image::RgbaImage::from_pixel(
            canvas_width,
            canvas_height,
            image::Rgba([244, 247, 250, 255]),
        );

        let left_x = margin;
        let right_x = margin + panel_width + divider_width;
        let top_y = margin;
        let content_y = top_y + header_height;

        fill_rgba_rect(
            &mut canvas,
            left_x,
            top_y,
            panel_width,
            header_height + panel_content_height,
            image::Rgba([255, 255, 255, 255]),
        );
        fill_rgba_rect(
            &mut canvas,
            right_x,
            top_y,
            panel_width,
            header_height + panel_content_height,
            image::Rgba([255, 255, 255, 255]),
        );
        fill_rgba_rect(
            &mut canvas,
            left_x,
            top_y,
            panel_width,
            header_height,
            image::Rgba([228, 235, 244, 255]),
        );
        fill_rgba_rect(
            &mut canvas,
            right_x,
            top_y,
            panel_width,
            header_height,
            image::Rgba([228, 235, 244, 255]),
        );

        blit_rgba(&mut canvas, &this_browser, left_x, content_y);
        blit_rgba(&mut canvas, &reference, right_x, content_y);
        draw_rgba_rect_outline(
            &mut canvas,
            left_x,
            top_y,
            panel_width,
            header_height + panel_content_height,
            image::Rgba([44, 57, 70, 255]),
        );
        draw_rgba_rect_outline(
            &mut canvas,
            right_x,
            top_y,
            panel_width,
            header_height + panel_content_height,
            image::Rgba([44, 57, 70, 255]),
        );
        draw_dashed_vertical_rgba_line(
            &mut canvas,
            margin + panel_width + divider_width / 2,
            top_y,
            header_height + panel_content_height,
            10,
            30,
            18,
            image::Rgba([0, 0, 0, 255]),
        );
        draw_ascii_label(
            &mut canvas,
            "THIS BROWSER",
            left_x + 18,
            top_y + 18,
            3,
            image::Rgba([18, 27, 36, 255]),
        );
        draw_ascii_label(
            &mut canvas,
            "REFERENCE",
            right_x + 18,
            top_y + 18,
            3,
            image::Rgba([18, 27, 36, 255]),
        );

        if let Some(parent) = output_path.parent() {
            fs::create_dir_all(parent)
                .unwrap_or_else(|error| panic!("failed to create {}: {error}", parent.display()));
        }
        canvas
            .save(output_path)
            .unwrap_or_else(|error| panic!("failed to write {}: {error}", output_path.display()));
    }

    fn blit_rgba(
        destination: &mut image::RgbaImage,
        source: &image::RgbaImage,
        x_offset: u32,
        y_offset: u32,
    ) {
        for (x, y, pixel) in source.enumerate_pixels() {
            destination.put_pixel(x_offset + x, y_offset + y, *pixel);
        }
    }

    fn fill_rgba_rect(
        image: &mut image::RgbaImage,
        x: u32,
        y: u32,
        width: u32,
        height: u32,
        color: image::Rgba<u8>,
    ) {
        for rect_y in y..(y + height).min(image.height()) {
            for rect_x in x..(x + width).min(image.width()) {
                image.put_pixel(rect_x, rect_y, color);
            }
        }
    }

    fn draw_rgba_rect_outline(
        image: &mut image::RgbaImage,
        x: u32,
        y: u32,
        width: u32,
        height: u32,
        color: image::Rgba<u8>,
    ) {
        fill_rgba_rect(image, x, y, width, 2, color);
        fill_rgba_rect(image, x, y + height.saturating_sub(2), width, 2, color);
        fill_rgba_rect(image, x, y, 2, height, color);
        fill_rgba_rect(image, x + width.saturating_sub(2), y, 2, height, color);
    }

    fn draw_dashed_vertical_rgba_line(
        image: &mut image::RgbaImage,
        center_x: u32,
        y: u32,
        height: u32,
        width: u32,
        dash: u32,
        gap: u32,
        color: image::Rgba<u8>,
    ) {
        let x = center_x.saturating_sub(width / 2);
        let mut cursor_y = y;
        let bottom = y + height;
        while cursor_y < bottom {
            let segment_height = dash.min(bottom - cursor_y);
            fill_rgba_rect(image, x, cursor_y, width, segment_height, color);
            cursor_y = cursor_y.saturating_add(dash + gap);
        }
    }

    fn draw_ascii_label(
        image: &mut image::RgbaImage,
        text: &str,
        x: u32,
        y: u32,
        scale: u32,
        color: image::Rgba<u8>,
    ) {
        let mut cursor_x = x;
        for ch in text.chars() {
            if ch == ' ' {
                cursor_x += scale * 4;
                continue;
            }
            if let Some(glyph) = ascii_label_glyph(ch) {
                for (row, bits) in glyph.iter().enumerate() {
                    for col in 0..5u32 {
                        if bits & (1u8 << (4 - col)) != 0 {
                            fill_rgba_rect(
                                image,
                                cursor_x + col * scale,
                                y + row as u32 * scale,
                                scale,
                                scale,
                                color,
                            );
                        }
                    }
                }
            }
            cursor_x += scale * 6;
        }
    }

    fn ascii_label_glyph(ch: char) -> Option<[u8; 7]> {
        match ch {
            'A' => Some([
                0b01110, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b10001,
            ]),
            'B' => Some([
                0b11110, 0b10001, 0b10001, 0b11110, 0b10001, 0b10001, 0b11110,
            ]),
            'C' => Some([
                0b01111, 0b10000, 0b10000, 0b10000, 0b10000, 0b10000, 0b01111,
            ]),
            'E' => Some([
                0b11111, 0b10000, 0b10000, 0b11110, 0b10000, 0b10000, 0b11111,
            ]),
            'F' => Some([
                0b11111, 0b10000, 0b10000, 0b11110, 0b10000, 0b10000, 0b10000,
            ]),
            'H' => Some([
                0b10001, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b10001,
            ]),
            'I' => Some([
                0b11111, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100, 0b11111,
            ]),
            'N' => Some([
                0b10001, 0b11001, 0b10101, 0b10011, 0b10001, 0b10001, 0b10001,
            ]),
            'O' => Some([
                0b01110, 0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b01110,
            ]),
            'R' => Some([
                0b11110, 0b10001, 0b10001, 0b11110, 0b10100, 0b10010, 0b10001,
            ]),
            'S' => Some([
                0b01111, 0b10000, 0b10000, 0b01110, 0b00001, 0b00001, 0b11110,
            ]),
            'T' => Some([
                0b11111, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100,
            ]),
            'W' => Some([
                0b10001, 0b10001, 0b10001, 0b10101, 0b10101, 0b10101, 0b01010,
            ]),
            _ => None,
        }
    }

    fn color_layout_reference_index(rows: &[String]) -> String {
        format!(
            r#"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Color Layout PNG Reference</title>
<style>
body {{ margin: 0; padding: 24px; font-family: sans-serif; background: #f5f7fa; color: #17212b; }}
h1 {{ margin: 0 0 16px; }}
.pair {{ margin: 0 0 28px; padding-bottom: 28px; border-bottom: 1px solid #c9d1d9; }}
.pair h2 {{ margin: 0 0 12px; font-size: 16px; }}
.pair > div {{ display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; align-items: start; }}
.pair figure.wide {{ grid-column: 1 / -1; }}
figure {{ margin: 0; background: white; border: 1px solid #c9d1d9; }}
figcaption {{ padding: 8px 10px; font-weight: 700; background: #eef2f7; border-bottom: 1px solid #c9d1d9; }}
img {{ display: block; width: 100%; height: auto; image-rendering: auto; }}
@media (max-width: 900px) {{ .pair > div {{ grid-template-columns: 1fr; }} }}
</style>
</head>
<body>
<h1>Color Layout PNG Reference</h1>
<p>Manual visual comparison only. Left is AlmostThere captured from an actual browser window, right is Chrome/Chromium headless.</p>
{}
</body>
</html>
"#,
            rows.join("\n")
        )
    }

    fn html_escape(value: &str) -> String {
        value
            .replace('&', "&amp;")
            .replace('<', "&lt;")
            .replace('>', "&gt;")
            .replace('"', "&quot;")
    }

